insert into public.issue_types (id, label, label_hi, agency, owns, channels, ladder, role_ids, sort) values
  ('roads', 'Roads, footpaths', 'सड़क, फ़ुटपाथ', 'GMDA for master roads, MCG for internal roads', 'GMDA owns the master roads between sectors and the major corridors. MCG owns internal roads, lanes and footpaths. HSVP keeps its own sectors until transfer; developers keep licensed colonies under DTCP. NH-48 and the expressways are NHAI.', '[{"k":"Portal","v":"GMDA integrated grievance portal","href":"https://services.gmda.gov.in/","ic":"link"},{"k":"Toll-free","v":"1800 180 1817","href":"tel:18001801817","ic":"phone"},{"k":"WhatsApp","v":"78400 01817, with a photo","href":"https://wa.me/917840001817","ic":"chat"},{"k":"App","v":"myGurugram","ic":"app"},{"k":"Highways","v":"NHAI 1033","href":"tel:1033","ic":"phone"}]'::jsonb, '["Ticket on the portal; keep the number. Only you can close it.","No action in time: the officer named on the ticket, then the zone Joint Commissioner or Executive Engineer.","Still pending: MCG Commissioner and Mayor, or GMDA CEO.","Final: CM Window, with every ticket number attached."]'::jsonb, array['gmda','mcg','hsvp','dtcp','nhai','councillor','je']::text[], 0),
  ('waste', 'Garbage', 'कचरा', 'MCG sanitation wing', 'Door-to-door collection, sweeping, collection points, bulk waste and debris. Societies producing 100 kg a day or more must process wet waste on site under the 2016 rules.', '[{"k":"Portal","v":"GMDA integrated grievance portal","href":"https://services.gmda.gov.in/","ic":"link"},{"k":"Toll-free","v":"1800 180 1817","href":"tel:18001801817","ic":"phone"},{"k":"WhatsApp","v":"78400 01817, with a photo","href":"https://wa.me/917840001817","ic":"chat"},{"k":"App","v":"myGurugram","ic":"app"},{"k":"Central record","v":"Swachhata app","href":"https://swachhbharaturban.gov.in/","ic":"app"}]'::jsonb, '["Ticket on the portal or the Swachhata app; keep the number.","Not attended: the ward sanitary inspector, then the zone Joint Commissioner.","Still pending: MCG Commissioner and Mayor.","Final: CM Window with the ticket history."]'::jsonb, array['mcg','ulb','mohua','councillor','je','rwa']::text[], 1),
  ('water', 'Water, sewer', 'पानी, सीवर', 'GMDA for bulk supply, MCG for distribution', 'GMDA runs the treatment plants, master water lines and master sewers. MCG owns distribution and internal sewers inside sectors; HSVP in its own sectors. Tankers during a shortage come through the same ticket.', '[{"k":"Portal","v":"GMDA integrated grievance portal","href":"https://services.gmda.gov.in/","ic":"link"},{"k":"Toll-free","v":"1800 180 1817","href":"tel:18001801817","ic":"phone"},{"k":"WhatsApp","v":"78400 01817, with a photo","href":"https://wa.me/917840001817","ic":"chat"},{"k":"App","v":"myGurugram","ic":"app"}]'::jsonb, '["Ticket on the portal; keep the number. Only you can close it.","No action in time: the officer named on the ticket, then the zone Joint Commissioner or Executive Engineer.","Still pending: MCG Commissioner and Mayor, or GMDA CEO.","Final: CM Window, with every ticket number attached."]'::jsonb, array['gmda','mcg','hsvp','je']::text[], 2),
  ('drains', 'Drains, flooding', 'नाले, जलभराव', 'GMDA for master drains, MCG for internal drains', 'GMDA owns the master storm drains and natural creeks. MCG owns internal drains, desilting and road gullies. In the monsoon the district control room coordinates emergency pumping.', '[{"k":"Portal","v":"GMDA integrated grievance portal","href":"https://services.gmda.gov.in/","ic":"link"},{"k":"Toll-free","v":"1800 180 1817","href":"tel:18001801817","ic":"phone"},{"k":"WhatsApp","v":"78400 01817, with a photo","href":"https://wa.me/917840001817","ic":"chat"},{"k":"App","v":"myGurugram","ic":"app"},{"k":"District","v":"Control room and helplines","href":"https://gurugram.gov.in/helpline/","ic":"phone"}]'::jsonb, '["Ticket on the portal; keep the number. Only you can close it.","No action in time: the officer named on the ticket, then the zone Joint Commissioner or Executive Engineer.","Still pending: MCG Commissioner and Mayor, or GMDA CEO.","Final: CM Window, with every ticket number attached."]'::jsonb, array['gmda','mcg','dc','je']::text[], 3),
  ('lights', 'Streetlights', 'स्ट्रीट लाइट', 'MCG for internal roads, GMDA for master roads', 'Dark stretches, faulty poles and timers on internal roads are MCG; on sector-dividing and master roads they are GMDA. Quote the pole number if it is painted on.', '[{"k":"Portal","v":"GMDA integrated grievance portal","href":"https://services.gmda.gov.in/","ic":"link"},{"k":"Toll-free","v":"1800 180 1817","href":"tel:18001801817","ic":"phone"},{"k":"WhatsApp","v":"78400 01817, with a photo","href":"https://wa.me/917840001817","ic":"chat"},{"k":"App","v":"myGurugram","ic":"app"}]'::jsonb, '["Ticket on the portal; keep the number. Only you can close it.","No action in time: the officer named on the ticket, then the zone Joint Commissioner or Executive Engineer.","Still pending: MCG Commissioner and Mayor, or GMDA CEO.","Final: CM Window, with every ticket number attached."]'::jsonb, array['mcg','gmda','je']::text[], 4),
  ('parks', 'Parks, trees', 'पार्क, पेड़', 'MCG horticulture; HSVP in its sectors; Forest Department for trees', 'Neighbourhood parks are MCG horticulture. Green belts along HSVP roads are HSVP. Felling or damaging a tree needs Forest Department permission; report illegal felling to the Forest Department and the police.', '[{"k":"Portal","v":"GMDA integrated grievance portal","href":"https://services.gmda.gov.in/","ic":"link"},{"k":"Toll-free","v":"1800 180 1817","href":"tel:18001801817","ic":"phone"},{"k":"WhatsApp","v":"78400 01817, with a photo","href":"https://wa.me/917840001817","ic":"chat"},{"k":"App","v":"myGurugram","ic":"app"}]'::jsonb, '["Ticket on the portal; keep the number. Only you can close it.","No action in time: the officer named on the ticket, then the zone Joint Commissioner or Executive Engineer.","Still pending: MCG Commissioner and Mayor, or GMDA CEO.","Final: CM Window, with every ticket number attached."]'::jsonb, array['mcg','hsvp']::text[], 5),
  ('traffic', 'Traffic', 'ट्रैफ़िक', 'Gurugram Traffic Police; GMDA for signals', 'Enforcement, wrong-side driving and parking are the Traffic Police. Faulty signals, signage and junction design are GMDA. Vendors and structures on roads are MCG enforcement.', '[{"k":"Emergency","v":"112","href":"tel:112","ic":"phone"},{"k":"Police","v":"Haryana Police portal","href":"https://haryanapolice.gov.in/","ic":"link"},{"k":"Signals","v":"GMDA integrated portal","href":"https://services.gmda.gov.in/","ic":"link"},{"k":"Toll-free","v":"1800 180 1817","href":"tel:18001801817","ic":"phone"}]'::jsonb, '["Traffic Police for enforcement; a GMDA ticket for signals and engineering.","Not attended: the ACP Traffic of the zone, then the DCP Traffic.","Still pending: the Commissioner of Police, Gurugram.","Final: CM Window, or a Forum policy dialogue for a recurring junction."]'::jsonb, array['police','gmda','mcg']::text[], 6),
  ('power', 'Electricity', 'बिजली', 'DHBVN', 'Outages, tripping, broken poles, meter faults and billing disputes. Restoration and meter timelines are set by the Haryana Electricity Regulatory Commission.', '[{"k":"Helpline","v":"1912","href":"tel:1912","ic":"phone"},{"k":"Portal","v":"DHBVN consumer portal","href":"https://dhbvn.org.in/","ic":"link"}]'::jsonb, '["Register on 1912 or the portal; keep the complaint number.","Not resolved: the SDO (Operation), then the Executive Engineer.","Still pending: the Consumer Grievance Redressal Forum, DHBVN.","Final: the Electricity Ombudsman, Haryana."]'::jsonb, array['dhbvn']::text[], 7),
  ('pollution', 'Air, noise', 'हवा, शोर', 'HSPCB regional office, Gurugram', 'Construction dust, industrial emissions, noise and waste burning. Burning on public land is also MCG. Under GRAP, the Commission for Air Quality Management sets NCR-wide restrictions.', '[{"k":"Central app","v":"Sameer (CPCB)","href":"https://cpcb.nic.in/","ic":"app"},{"k":"State board","v":"HSPCB","href":"https://hspcb.gov.in/","ic":"link"},{"k":"Portal","v":"GMDA portal, air-monitoring cell","href":"https://services.gmda.gov.in/","ic":"link"},{"k":"Toll-free","v":"1800 180 1817","href":"tel:18001801817","ic":"phone"}]'::jsonb, '["Complaint on Sameer or the GMDA portal, with photo and time.","Not attended: the HSPCB Regional Officer, Gurugram.","Still pending: Member Secretary, HSPCB, and the Deputy Commissioner.","Final: CM Window, or CPGRAMS for CPCB and CAQM."]'::jsonb, array['hspcb','caqm','mcg','dc']::text[], 8),
  ('animals', 'Stray animals', 'आवारा पशु', 'MCG veterinary wing', 'Stray dog sterilisation and vaccination, stray cattle, carcass removal and dog-bite follow-up.', '[{"k":"Portal","v":"GMDA integrated grievance portal","href":"https://services.gmda.gov.in/","ic":"link"},{"k":"Toll-free","v":"1800 180 1817","href":"tel:18001801817","ic":"phone"},{"k":"WhatsApp","v":"78400 01817, with a photo","href":"https://wa.me/917840001817","ic":"chat"},{"k":"App","v":"myGurugram","ic":"app"}]'::jsonb, '["Ticket on the portal; keep the number. Only you can close it.","No action in time: the officer named on the ticket, then the zone Joint Commissioner or Executive Engineer.","Still pending: MCG Commissioner and Mayor, or GMDA CEO.","Final: CM Window, with every ticket number attached."]'::jsonb, array['mcg','je']::text[], 9),
  ('construction', 'Illegal construction', 'अवैध निर्माण', 'MCG town planning; DTCP for licensed colonies; HSVP in its sectors', 'Unauthorised floors, commercial use of residential plots and encroachment inside municipal limits are MCG. Licensed private colonies are the District Town Planner. HSVP sectors are the HSVP Estate Officer.', '[{"k":"Portal","v":"GMDA integrated grievance portal","href":"https://services.gmda.gov.in/","ic":"link"},{"k":"Toll-free","v":"1800 180 1817","href":"tel:18001801817","ic":"phone"},{"k":"WhatsApp","v":"78400 01817, with a photo","href":"https://wa.me/917840001817","ic":"chat"},{"k":"App","v":"myGurugram","ic":"app"},{"k":"DTCP","v":"Town and Country Planning","href":"https://tcpharyana.gov.in/","ic":"link"},{"k":"HSVP","v":"HSVP","href":"https://hsvphry.org.in/","ic":"link"}]'::jsonb, '["Written complaint with photos, plus a ticket on the portal.","Not attended: Senior Town Planner (MCG) or District Town Planner (DTCP).","Still pending: MCG Commissioner or Director, Town and Country Planning.","Final: CM Window."]'::jsonb, array['mcg','dtcp','hsvp']::text[], 10),
  ('property', 'Property tax', 'संपत्ति कर', 'MCG', 'Property-tax assessment and correction, building plans, occupation and no-dues certificates. Most are notified services with fixed time limits under the Right to Service Act.', '[{"k":"Portal","v":"ULB property tax and services","href":"https://ulbhryndc.org/","ic":"link"},{"k":"Services","v":"Saral Haryana","href":"https://saralharyana.gov.in/","ic":"link"},{"k":"MCG","v":"mcg.gov.in","href":"https://www.mcg.gov.in/","ic":"link"}]'::jsonb, '["Apply online; keep the application number.","Past the notified limit: the Auto Appeal System escalates for you.","Still pending: Grievance Officer, then the Right to Service Commission.","Parallel route: CM Window."]'::jsonb, array['mcg','ulb','rts']::text[], 11),
  ('housing', 'Builders, societies', 'बिल्डर, सोसाइटी', 'HRERA Gurugram; DTCP; District Registrar', 'Delayed possession and defects go to HRERA. Maintenance handover and licence conditions are DTCP. Disputes inside an RWA or AOA go to the District Registrar under the 2012 Act.', '[{"k":"HRERA","v":"HRERA Gurugram","href":"https://haryanarera.gov.in/","ic":"link"},{"k":"DTCP","v":"Town and Country Planning","href":"https://tcpharyana.gov.in/","ic":"link"},{"k":"District","v":"District Registrar, Firms and Societies","href":"https://gurugram.gov.in/","ic":"link"}]'::jsonb, '["File with HRERA or DTCP with the agreement and payment record.","HRERA: appeal to the Real Estate Appellate Tribunal.","DTCP: Director, Town and Country Planning, then CM Window.","Society-wide patterns go to a Forum policy dialogue."]'::jsonb, array['hrera','dtcp','dc']::text[], 12),
  ('safety', 'Police, cyber', 'पुलिस, साइबर', 'Gurugram Police', 'Crime, harassment, threats, domestic violence and cyber fraud. Any station must register a Zero FIR for a cognisable offence; you get a free copy of the FIR.', '[{"k":"Emergency","v":"112","href":"tel:112","ic":"phone"},{"k":"Women","v":"181","href":"tel:181","ic":"phone"},{"k":"Cyber fraud","v":"1930, within the first hour","href":"tel:1930","ic":"phone"},{"k":"Portal","v":"cybercrime.gov.in","href":"https://cybercrime.gov.in/","ic":"link"},{"k":"Police","v":"Haryana Police","href":"https://haryanapolice.gov.in/","ic":"link"}]'::jsonb, '["112 in an emergency; otherwise the station or online.","FIR refused: written complaint to the DCP of the zone.","Still refused: Commissioner of Police, or the Judicial Magistrate.","Cyber fraud: 1930 first, then the portal, then the station."]'::jsonb, array['police']::text[], 13),
  ('consumer', 'Consumer', 'उपभोक्ता', 'National Consumer Helpline; District Commission, Gurugram', 'Defective goods, unfair charges, deficient services, online disputes. The District Commission hears claims up to 50 lakh rupees; the State Commission up to 2 crore.', '[{"k":"Helpline","v":"1915","href":"tel:1915","ic":"phone"},{"k":"Portal","v":"consumerhelpline.gov.in","href":"https://consumerhelpline.gov.in/","ic":"link"},{"k":"File online","v":"e-Daakhil","href":"https://edaakhil.nic.in/","ic":"link"}]'::jsonb, '["Written complaint to the seller; keep the record.","No resolution: 1915 mediation with the company.","Still unresolved: District Commission, Gurugram, on e-Daakhil.","Appeal to the State Commission, Panchkula."]'::jsonb, array['consumer']::text[], 14),
  ('rti', 'RTI', 'सूचना (RTI)', 'The Public Information Officer of that office', 'Any record a public authority holds: files, tenders, inspection reports, budgets. Reply due in 30 days, 48 hours where life or liberty is at stake.', '[{"k":"Central","v":"RTI Online","href":"https://rtionline.gov.in/","ic":"link"},{"k":"State","v":"PIO of MCG, GMDA, HSVP or DTCP, with a 10 rupee fee","ic":"mail"}]'::jsonb, '["Application to the PIO with the fee.","No reply in 30 days: first appeal in the same office.","Second appeal: State Information Commission (CIC for central bodies).","The Forum can help draft a precise request."]'::jsonb, '{}'::text[], 15),
  ('other', 'Something else', 'कुछ और', 'Depends on the subject; the Forum maps it', 'A scheme not reaching you, a service that needs redesign, an idea for the city. The Forum reads every submission and points it to a desk or a policy dialogue.', '[{"k":"State","v":"CM Window","href":"https://cmharyanacell.nic.in/","ic":"link"},{"k":"Central","v":"CPGRAMS","href":"https://pgportal.gov.in/","ic":"link"},{"k":"Forum","v":"Report it here","href":"#/report","ic":"chat"}]'::jsonb, '["Send it through the Forum.","A volunteer maps it within three working days.","Recurring themes go to a policy dialogue."]'::jsonb, array['cm','chapter']::text[], 16)
